// Normalise the inbound message into a structured support intent.
// Sarvam supplies the language when reachable; the keyword rules below are
// the fallback so intake never blocks on a third-party service.
const incoming = $('Issue Intake Webhook').first().json.body || {};
const text = String(incoming.message || '');
const low = text.toLowerCase();

let language = 'en-IN';
let script = 'Latin';
let source = 'fallback';

const lid = $json || {};
if (lid.language_code) {
  language = lid.language_code;
  script = lid.script_code || script;
  source = 'sarvam';
} else if (/[\u0900-\u097F]/.test(text)) {
  language = 'hi-IN';
  script = 'Devanagari';
}

const any = (words) => words.some((w) => low.includes(w.toLowerCase()));
const DEBIT = ['कट गया', 'debited', 'debit', 'पैसा गया'];
const NOT_RECEIVED = ['नहीं मिला', 'not received', 'not credited', 'nahi mila'];
const DELAY = ['delay', 'delayed', 'देर', 'pending', 'stuck'];
const REFUND = ['refund', 'रिफंड', 'वापस'];
const STRONG_NEG = ['तीन बार', 'कई बार', 'अभी तक', 'third time', 'शिकायत कर चुका', 'worst', 'fed up'];

let intent = 'general_support';
if (any(DEBIT) && any(NOT_RECEIVED)) intent = 'payment_failed_after_debit';
else if (any(REFUND)) intent = 'refund_status';
else if (any(DELAY)) intent = 'payment_delayed';
else if (any(DEBIT)) intent = 'payment_failed_after_debit';

let sentiment = 'neutral';
if (any(STRONG_NEG) || (text.match(/!/g) || []).length >= 2) sentiment = 'strongly_negative';
else if (any(['problem', 'issue', 'परेशान', 'failed'])) sentiment = 'negative';

const amountMatch = text.match(/(?:₹|rs\.?|inr)\s*([\d,]+)|([\d,]{3,})/i);
const rawAmount = amountMatch ? (amountMatch[1] || amountMatch[2]) : null;

return [{
  json: {
    success: true,
    analysis: {
      intent,
      language,
      script,
      sentiment,
      amount_mentioned: rawAmount ? Number(String(rawAmount).replace(/,/g, '')) : null,
      normalized_text: text.trim(),
      source,
      source_detail: source === 'sarvam' ? 'Sarvam text-lid' : 'Local classifier (n8n)'
    }
  }
}];
